ALTER TABLE public.profiles ADD COLUMN is_suspended boolean NOT NULL DEFAULT false;
ALTER TABLE public.profiles ALTER COLUMN trial_ends_at SET DEFAULT (now() + interval '12 minutes');
ALTER TABLE public.site_appearance ADD COLUMN slides jsonb NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE public.site_appearance ADD COLUMN group_url text NOT NULL DEFAULT 'https://chat.whatsapp.com/KxKzfO4MsaY2YmAjQD526L?s=cl&p=a&iam=2';
ALTER TABLE public.payments ADD COLUMN granted_days integer NOT NULL DEFAULT 0;
ALTER TABLE public.payments ADD COLUMN adjustment_note text;
UPDATE public.payments p SET granted_days=k.days FROM public.packages k WHERE p.package=k.id AND p.status='approved';
CREATE TABLE public.app_owner (id text PRIMARY KEY DEFAULT 'main', user_id uuid NOT NULL);
GRANT SELECT ON public.app_owner TO authenticated;
GRANT ALL ON public.app_owner TO service_role;
ALTER TABLE public.app_owner ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_read ON public.app_owner FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
INSERT INTO public.app_owner(id,user_id) SELECT 'main',p.id FROM public.profiles p JOIN public.user_roles r ON r.user_id=p.id AND r.role='admin' ORDER BY p.created_at LIMIT 1;
CREATE FUNCTION public.is_app_owner() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.app_owner WHERE user_id=auth.uid()) $$;
REVOKE ALL ON FUNCTION public.is_app_owner() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_app_owner() TO authenticated;
CREATE TABLE public.payment_networks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, receiving_number text NOT NULL, receiving_name text NOT NULL, ussd text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, sort_order integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.payment_networks TO anon,authenticated;
GRANT INSERT,UPDATE,DELETE ON public.payment_networks TO authenticated;
GRANT ALL ON public.payment_networks TO service_role;
ALTER TABLE public.payment_networks ENABLE ROW LEVEL SECURITY;
CREATE POLICY networks_read ON public.payment_networks FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY networks_admin ON public.payment_networks FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.app_likes (visitor_id uuid PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.app_likes TO service_role;
ALTER TABLE public.app_likes ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.outside_likes(_visitor uuid DEFAULT NULL, _like boolean DEFAULT NULL) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF _visitor IS NOT NULL AND _like IS NOT NULL THEN IF _like THEN INSERT INTO public.app_likes(visitor_id) VALUES(_visitor) ON CONFLICT DO NOTHING; ELSE DELETE FROM public.app_likes WHERE visitor_id=_visitor; END IF; END IF; RETURN (SELECT count(*) FROM public.app_likes); END $$;
REVOKE ALL ON FUNCTION public.outside_likes(uuid,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.outside_likes(uuid,boolean) TO anon,authenticated;
CREATE TABLE public.admin_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor uuid NOT NULL, target uuid NOT NULL, action text NOT NULL, note text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.admin_audit TO authenticated;
GRANT ALL ON public.admin_audit TO service_role;
ALTER TABLE public.admin_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_admin_read ON public.admin_audit FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.manage_admin(_user_id uuid,_promote boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_app_owner() THEN RAISE EXCEPTION 'Mmiliki pekee'; END IF; IF EXISTS(SELECT 1 FROM public.app_owner WHERE user_id=_user_id) THEN RAISE EXCEPTION 'Mmiliki hawezi kuondolewa'; END IF; IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=_user_id) THEN RAISE EXCEPTION 'Mteja hayupo'; END IF; IF _promote THEN INSERT INTO public.user_roles(user_id,role) VALUES(_user_id,'admin') ON CONFLICT DO NOTHING; ELSE DELETE FROM public.user_roles WHERE user_id=_user_id AND role='admin'; END IF; INSERT INTO public.admin_audit(actor,target,action) VALUES(auth.uid(),_user_id,CASE WHEN _promote THEN 'promote' ELSE 'demote' END); END $$;
REVOKE ALL ON FUNCTION public.manage_admin(uuid,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.manage_admin(uuid,boolean) TO authenticated;
CREATE FUNCTION public.suspend_customer(_user_id uuid,_suspended boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role='admin') THEN RAISE EXCEPTION 'Huruhusiwi kusimamisha msimamizi'; END IF; UPDATE public.profiles SET is_suspended=_suspended WHERE id=_user_id; IF NOT FOUND THEN RAISE EXCEPTION 'Mteja hayupo'; END IF; INSERT INTO public.admin_audit(actor,target,action) VALUES(auth.uid(),_user_id,CASE WHEN _suspended THEN 'suspend' ELSE 'resume' END); END $$;
REVOKE ALL ON FUNCTION public.suspend_customer(uuid,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.suspend_customer(uuid,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(729341); INSERT INTO public.profiles(id,display_name,contact) VALUES(new.id,coalesce(new.raw_user_meta_data->>'display_name',split_part(new.email,'@',1)),coalesce(new.raw_user_meta_data->>'contact',new.email)); IF NOT EXISTS(SELECT 1 FROM public.app_owner) THEN INSERT INTO public.app_owner(id,user_id) VALUES('main',new.id); INSERT INTO public.user_roles(user_id,role) VALUES(new.id,'admin'); END IF; INSERT INTO public.user_roles(user_id,role) VALUES(new.id,'user'); RETURN new; END $$;
CREATE OR REPLACE FUNCTION public.review_payment(_payment_id uuid,_approve boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.payments; d integer; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Not allowed'; END IF; SELECT * INTO p FROM public.payments WHERE id=_payment_id FOR UPDATE; IF p.id IS NULL OR p.status<>'pending' THEN RAISE EXCEPTION 'Malipo yameshashughulikiwa'; END IF; SELECT days INTO d FROM public.packages WHERE id=p.package; IF _approve AND d IS NULL THEN RAISE EXCEPTION 'Kifurushi hakipo'; END IF; PERFORM 1 FROM public.profiles WHERE id=p.user_id FOR UPDATE; UPDATE public.payments SET status=CASE WHEN _approve THEN 'approved' ELSE 'rejected' END,reviewed_at=now(),granted_days=CASE WHEN _approve THEN d ELSE 0 END WHERE id=p.id; IF _approve THEN UPDATE public.profiles SET subscription_ends_at=greatest(coalesce(subscription_ends_at,now()),now())+make_interval(days=>d) WHERE id=p.user_id; END IF; INSERT INTO public.admin_audit(actor,target,action) VALUES(auth.uid(),p.user_id,CASE WHEN _approve THEN 'payment_approve' ELSE 'payment_reject' END); END $$;
CREATE FUNCTION public.correct_payment(_payment_id uuid,_package text,_amount integer,_refund boolean,_note text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.payments; k public.packages; base timestamptz; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Not allowed'; END IF; IF length(trim(_note))<3 THEN RAISE EXCEPTION 'Andika sababu au kumbukumbu ya kurejesha'; END IF; SELECT * INTO p FROM public.payments WHERE id=_payment_id FOR UPDATE; IF p.id IS NULL OR p.status='refunded' THEN RAISE EXCEPTION 'Malipo hayapo au yamerudishwa'; END IF; IF NOT _refund THEN SELECT * INTO k FROM public.packages WHERE id=_package AND active; IF k.id IS NULL OR _amount<>k.price THEN RAISE EXCEPTION 'Kiasi lazima kilingane na bei ya kifurushi'; END IF; END IF; SELECT greatest(now(),coalesce(subscription_ends_at,now())-make_interval(days=>p.granted_days)) INTO base FROM public.profiles WHERE id=p.user_id FOR UPDATE; IF base IS NULL THEN RAISE EXCEPTION 'Mteja hayupo'; END IF; UPDATE public.profiles SET subscription_ends_at=CASE WHEN _refund THEN base ELSE base+make_interval(days=>k.days) END WHERE id=p.user_id; UPDATE public.payments SET status=CASE WHEN _refund THEN 'refunded' ELSE 'approved' END,package=CASE WHEN _refund THEN package ELSE k.id END,amount=CASE WHEN _refund THEN amount ELSE k.price END,granted_days=CASE WHEN _refund THEN 0 ELSE k.days END,adjustment_note=trim(_note),reviewed_at=now() WHERE id=p.id; INSERT INTO public.admin_audit(actor,target,action,note) VALUES(auth.uid(),p.user_id,CASE WHEN _refund THEN 'manual_refund' ELSE 'payment_correct' END,trim(_note)); END $$;
REVOKE ALL ON FUNCTION public.correct_payment(uuid,text,integer,boolean,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.correct_payment(uuid,text,integer,boolean,text) TO authenticated;